verbs.source:
verb :can_be_attached_by(who) rxd {
  /* Mounting the acts feature is a seed/owner act on the consumer side
     ($case:initialize); the feature itself is freely attachable. */
  return true;
}

verb :act(type, payload) rx {
  /* Internal emission primitive (acts kernel S2.4). Requires a sequenced
     turn on this room's own log (direct routes carry seq == -1), called
     from this room's own verbs (caller == this). Validates the payload
     against the declared event schema, folds every attached projection
     inside the same turn, then records the act observation. Any fold
     failure aborts the whole turn: fail-closed. */
  if (seq < 1 || space != this) { raise { code: "E_INVARG", message: "acts require a sequenced turn on this room" }; }
  if (caller != this) { raise { code: "E_PERM", message: "acts are emitted by room verbs only" }; }
  let shape = event_schema(this, type);
  if (shape == null) { raise { code: "E_INVARG", message: "unknown act type", value: type }; }
  this:_validate_payload(type, shape, payload);
  let act = { "type": type, "version": 1, "payload": payload };
  /* Folds receive the act plus its envelope seq, injected here (live) or
     by :rebuild_from (recorded). The observed act body stays free of
     envelope fields — the log entry is the envelope. */
  let fold_input = { "type": type, "version": 1, "payload": payload, "seq": seq };
  for p in this.projections {
    if (valid(p) && (type in p.consumes)) { p:fold(fold_input); }
  }
  observe(act);
  return act;
}

verb :_validate_payload(type, shape, payload) rx {
  /* Closed flat shape subset (S2.2): obj, str, bool, int, float, num,
     list, map. Every declared key is required; undeclared keys refuse.
     Exact typing: a "str" field refuses live object refs (refs are
     strings at the VM level - an obj must not pass as a code/label),
     and "obj" requires a live ref. */
  if (typeof(payload) != "map") { raise { code: "E_INVARG", message: "act payload must be a map", value: type }; }
  for pk, pv in payload {
    if (!(pk in shape)) { raise { code: "E_INVARG", message: "undeclared act payload key", value: pk }; }
  }
  for k, t in shape {
    if (!(k in payload)) { raise { code: "E_INVARG", message: "missing act payload key", value: k }; }
    let val = payload[k];
    let ok = false;
    if (t == "obj") { ok = typeof(val) == "string" && valid(val); }
    else if (t == "str") { ok = typeof(val) == "string" && !valid(val); }
    else if (t == "bool") { ok = typeof(val) == "boolean"; }
    else if (t == "int") { ok = typeof(val) == "number" && floor(val) == val; }
    else if (t == "float" || t == "num") { ok = typeof(val) == "number"; }
    else if (t == "list") { ok = typeof(val) == "list"; }
    else if (t == "map") { ok = typeof(val) == "map"; }
    else { raise { code: "E_INVARG", message: "unsupported shape tag", value: t }; }
    if (!ok) { raise { code: "E_INVARG", message: "act payload type mismatch", value: k }; }
  }
  return true;
}

verb :fold(act) rx {
  /* Subclass responsibility (S2.3): deterministic given (rows, act), the
     sole writer of this.rows, O(payload), no clock, no foreign reads.
     The act input carries the envelope seq as act["seq"]. The base
     refuses so an unimplemented projection fails loudly. */
  raise { code: "E_VERBNF", message: "projection must implement :fold" };
}

verb :view(opts) rxd {
  /* The one authoritative bounded read (S2.3). Pages rows in key order
     with a continuation cursor: pass opts["after"] = the previous
     page's "cursor" to fetch the next page (a stale/unknown cursor
     yields an empty page). at_seq is the seq of the LAST CONSUMED act -
     a conservative completeness watermark, not the room's head seq.
     Each row renders through :view_row so subclasses join
     object-authoritative facts at view time without mirroring them. */
  if (typeof(opts) != "map") { opts = {}; }
  let limit = 50;
  if ("limit" in opts) { limit = toint(opts["limit"]); }
  if (limit < 1 || limit > 200) { limit = 50; }
  let after = "";
  if ("after" in opts) { after = to_string(opts["after"]); }
  let skipping = after != "";
  let page = [];
  let cursor = null;
  let has_more = false;
  for k in keys(this.rows) {
    if (skipping) { if (k == after) { skipping = false; } continue; }
    if (length(page) >= limit) { has_more = true; break; }
    page = page + [this:view_row(k, this.rows[k])];
    cursor = k;
  }
  return { "page": page, "at_seq": this.at_seq, "cursor": cursor, "has_more": has_more };
}

verb :view_row(key, row) rx {
  /* Default rendering: the stored row itself. */
  return row;
}

verb :rebuild_from(source_space, page_budget) rxd {
  /* Operator rebuild (gate 1): re-fold recorded acts from the source
     log. Incremental and idempotent: resumes after the furthest of
     at_seq (live folds) and rebuild_scan_seq (prior rebuild scans), so
     repeated calls never double-fold. Bounded: processes at most one
     replay page per call - callers loop while done == false. A
     reset/reseed path belongs with genesis replacement, not here.
     Owner/wizard only. Skips failed entries. */
  if (actor != this.owner && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "rebuild is owner-only" }; }
  let budget = 100;
  if (typeof(page_budget) == "number" && page_budget >= 1 && page_budget <= 100) { budget = toint(page_budget); }
  let from = this.at_seq;
  if (this.rebuild_scan_seq > from) { from = this.rebuild_scan_seq; }
  from = from + 1;
  let entries = source_space:replay(from, budget);
  let scanned = from - 1;
  for e in entries {
    scanned = e["seq"];
    if (!e["applied_ok"]) { continue; }
    for o in e["observations"] {
      if (typeof(o) == "map" && ("type" in o) && ("payload" in o) && ("version" in o) && (o["type"] in this.consumes)) {
        let input = o;
        input["seq"] = e["seq"];
        this:fold(input);
      }
    }
  }
  this.rebuild_scan_seq = scanned;
  return { "at_seq": this.at_seq, "scanned_seq": scanned, "done": length(entries) < budget };
}

verb :fold(act) rx {
  /* Sole writer of this.rows. Raising here aborts the whole turn,
     including the domain verb's physical effects (fail-closed, S2.3);
     E_QUOTA at row_cap is the declared refuse-overflow policy. Uses the
     injected act["seq"], never the frame global, so rebuild outside a
     sequenced turn reproduces rows exactly. */
  let ty = act["type"];
  let p = act["payload"];
  let rows = this.rows;
  if (ty == "tasks.opened") {
    if (length(rows) >= this.row_cap) { raise { code: "E_QUOTA", message: "board row cap", value: this.row_cap }; }
    rows[to_string(p["task"])] = { "task": p["task"], "kind": p["kind"], "labels": p["labels"], "obligations": p["obligations"], "waits": [], "links": [], "phase": "active", "opened_seq": act["seq"], "last_change_seq": act["seq"] };
  } else {
    let key = to_string(p["task"]);
    if (!(key in rows)) { raise { code: "E_INVARG", message: "act for unknown task", value: key }; }
    let row = rows[key];
    if (ty == "tasks.passed") {
      let obs = [];
      for o in row["obligations"] {
        if (typeof(o) == "map" && o["key"] == p["obligation"]) { let m = o; m["met"] = true; obs = obs + [m]; }
        else { obs = obs + [o]; }
      }
      row["obligations"] = obs;
    } else if (ty == "tasks.closed") {
      row["phase"] = "closed";
    }
    row["last_change_seq"] = act["seq"];
    rows[key] = row;
  }
  this.rows = rows;
  this.at_seq = act["seq"];
}

verb :view_row(key, row) rx {
  /* Joins per page row (S5.2): artifact name and the single lease fact
     read at view time, never mirrored. claimed iff the task is not in
     the case. Obligation cursor computed from row state. */
  let t = row["task"];
  let name = null;
  let holder = null;
  let claimed = false;
  if (valid(t)) {
    name = t.name;
    let loc = location(t);
    if (loc != location(this)) { holder = loc; claimed = true; }
  }
  let met = 0;
  let total = 0;
  let cursor = null;
  for o in row["obligations"] {
    total = total + 1;
    if (o["met"]) { met = met + 1; }
    else if (cursor == null) { cursor = o["key"]; }
  }
  return { "task": t, "name": name, "kind": row["kind"], "labels": row["labels"], "phase": row["phase"], "claimed": claimed, "holder": holder, "cursor": cursor, "obligations_met": met, "obligations_total": total, "opened_seq": row["opened_seq"], "last_change_seq": row["last_change_seq"] };
}

verb :fold(act) rx {
  /* Sole writer of this.rows and this.task_states (acts kernel S2.3).
     One row per task kind: { kind, open, claimed, closed }. The
     claimed/released/closed payloads carry no kind, so the fold keeps
     a per-task auxiliary index (task_states) beside the lane rows -
     bounded by aux_cap and by terminal EVICTION: a closed task's entry
     is removed (the domain refuses transitions out of closed, so no
     later act can need it). Both structures are written only here, so
     rebuild reproduces both. Deterministic given (projection state,
     act); injected act["seq"]; no clock; no foreign reads. Raising
     aborts the whole turn (fail-closed). */
  let ty = act["type"];
  let p = act["payload"];
  let key = to_string(p["task"]);
  let rows = this.rows;
  let states = this.task_states;
  if (ty == "tasks.opened") {
    let kind = p["kind"];
    if (!(kind in rows)) {
      if (length(rows) >= this.row_cap) { raise { code: "E_QUOTA", message: "kind lane cap", value: this.row_cap }; }
      rows[kind] = { "kind": kind, "open": 0, "claimed": 0, "closed": 0 };
    }
    if (length(states) >= this.aux_cap) { raise { code: "E_QUOTA", message: "kind lane aux cap", value: this.aux_cap }; }
    let opened = rows[kind];
    opened["open"] = opened["open"] + 1;
    rows[kind] = opened;
    states[key] = { "kind": kind, "state": "open" };
  } else {
    if (!(key in states)) { raise { code: "E_INVARG", message: "act for unknown task", value: key }; }
    let st = states[key];
    let lk = st["kind"];
    let lane = rows[lk];
    if (ty == "tasks.claimed") {
      if (st["state"] == "open") {
        lane["open"] = lane["open"] - 1;
        lane["claimed"] = lane["claimed"] + 1;
        st["state"] = "claimed";
      }
      states[key] = st;
    } else if (ty == "tasks.released") {
      if (st["state"] == "claimed") {
        lane["claimed"] = lane["claimed"] - 1;
        lane["open"] = lane["open"] + 1;
        st["state"] = "open";
      }
      states[key] = st;
    } else if (ty == "tasks.closed") {
      if (st["state"] == "open") { lane["open"] = lane["open"] - 1; lane["closed"] = lane["closed"] + 1; }
      else if (st["state"] == "claimed") { lane["claimed"] = lane["claimed"] - 1; lane["closed"] = lane["closed"] + 1; }
      /* Terminal eviction: rebuild the index without this task. The
         whole-map property write is already O(states); this filtered
         copy on the terminal transition only does not worsen it. */
      let kept = {};
      for sk, sv in states {
        if (sk != key) { kept[sk] = sv; }
      }
      states = kept;
    }
    rows[lk] = lane;
  }
  this.rows = rows;
  this.task_states = states;
  this.at_seq = act["seq"];
}

verb :initialize(row_cap) rxd {
  /* Seed-time setup: create the board projection co-anchored with the
     case (same anchor cluster, so SL2 atomicity covers fold writes).
     The $acts feature is attached per instance here ($space instances
     own-seed an empty features list, so the class-level attach — which
     exists to satisfy the installer's static this-call resolution —
     does not reach them). Owner/wizard only. */
  if (actor != this.owner && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "case initialize is owner-only" }; }
  this:add_feature($acts);
  let board = create($task_board, { owner: this.owner, name: "board", location: this });
  if (typeof(row_cap) == "number" && row_cap > 0) { board.row_cap = toint(row_cap); }
  this.projections = [board];
  return board;
}

verb :_board_row(task) rx {
  /* The authoritative board row for a task, or null. Domain verbs
     validate lifecycle transitions against fold state (kernel S5.1),
     never against contents scans or location alone. */
  if (length(this.projections) < 1) { return null; }
  let b = this.projections[1];
  let rows = b.rows;
  let key = to_string(task);
  if (!(key in rows)) { return null; }
  return rows[key];
}

verb :open_task(name, text, kind, labels, obligations) rxd {
  /* Domain verb: mints the task artifact (object-authoritative content),
     then records the coordination fact as an act in the same turn. */
  if (typeof(name) != "string" || name == "") { raise { code: "E_INVARG", message: "task name required" }; }
  if (typeof(labels) != "list") { labels = []; }
  if (typeof(obligations) != "list") { obligations = []; }
  let obs = [];
  for k in obligations { obs = obs + [{ "key": to_string(k), "met": false }]; }
  let t = create($note, { owner: actor, name: name, location: this });
  if (typeof(text) == "string" && text != "") { t:set_text(text); }
  this:act("tasks.opened", { "task": t, "kind": to_string(kind), "labels": labels, "obligations": obs });
  return t;
}

verb :claim(task) rxd {
  /* The move IS the lease; the act records the coordination fact in the
     same sequenced turn. Validated against the board row: a closed or
     dropped task cannot be re-claimed even though close_task returned
     it to the case physically (review finding 1, 2026-07-21).
     Fail-closed: if the fold refuses, the move rolls back with it. */
  let row = this:_board_row(task);
  if (row == null || row["phase"] != "active") { raise { code: "E_TRANSITION", message: "task is not claimable", value: task }; }
  if (!valid(task) || location(task) != this) { raise { code: "E_INVARG", message: "task not open here", value: task }; }
  moveto(task, actor);
  this:act("tasks.claimed", { "task": task, "holder": actor });
  return task;
}

verb :release(task) rxd {
  let row = this:_board_row(task);
  if (row == null || row["phase"] != "active") { raise { code: "E_TRANSITION", message: "task is not active", value: task }; }
  if (!valid(task) || location(task) != actor) { raise { code: "E_INVARG", message: "you do not hold that task", value: task }; }
  moveto(task, this);
  this:act("tasks.released", { "task": task });
  return task;
}

verb :pass_obligation(task, obligation) rxd {
  let row = this:_board_row(task);
  if (row == null || row["phase"] != "active") { raise { code: "E_TRANSITION", message: "task is not active", value: task }; }
  if (!valid(task) || location(task) != actor) { raise { code: "E_INVARG", message: "you do not hold that task", value: task }; }
  this:act("tasks.passed", { "task": task, "obligation": to_string(obligation) });
  return true;
}

verb :close_task(task, outcome_code) rxd {
  /* Terminal transition, once: closing a closed task refuses (the
     state machine is enforced at the domain, so folds may treat
     terminal states as final and evict auxiliary entries). */
  let row = this:_board_row(task);
  if (row == null || row["phase"] != "active") { raise { code: "E_TRANSITION", message: "task is not open", value: task }; }
  if (!valid(task)) { raise { code: "E_INVARG", message: "no such task", value: task }; }
  if (location(task) == actor) { moveto(task, this); }
  this:act("tasks.closed", { "task": task, "outcome_code": to_string(outcome_code) });
  return true;
}

verb :board(opts) rxd {
  /* Authoritative board read: delegates to the projection's view. */
  if (length(this.projections) < 1) { raise { code: "E_INVARG", message: "case has no board; run initialize" }; }
  let b = this.projections[1];
  return b:view(opts);
}

verb :journal(from_seq, limit) rxd {
  /* Paged log read (S3): the log IS the journal — no materialized copy.
     Returns act-typed observations with their envelope seq and ts. */
  let entries = this:replay(from_seq, limit);
  let out = [];
  for e in entries {
    for o in e["observations"] {
      if (typeof(o) == "map" && ("type" in o) && ("payload" in o) && ("version" in o)) {
        out = out + [{ "seq": e["seq"], "ts": e["ts"], "type": o["type"], "payload": o["payload"] }];
      }
    }
  }
  return out;
}
